#!/bin/bash

set -e

# Read in orb parameters
INSTALL_PATH=$(circleci env subst "${PARAM_INSTALL_PATH}")
VERIFY_CHECKSUMS="${PARAM_VERIFY_CHECKSUMS}"
VERSION=$(circleci env subst "${PARAM_VERSION}")

# Grype publishes a Linux release asset per CPU architecture. Map this
# machine onto the asset naming, and refuse anything else rather than
# installing a binary that cannot run.
if [[ "$(uname -s)" != "Linux" ]]; then
    echo "ERROR: Unsupported operating system: $(uname -s). This orb installs Linux builds of Grype."
    exit 1
fi
MACHINE_ARCH=$(uname -m)
case "${MACHINE_ARCH}" in
    x86_64)
        ARCH=amd64
        ;;
    aarch64|arm64)
        ARCH=arm64
        ;;
    *)
        echo "ERROR: Unsupported CPU architecture: ${MACHINE_ARCH}. Supported: x86_64 (amd64), aarch64/arm64 (arm64)."
        exit 1
        ;;
esac

# Print command arguments for debugging purposes.
echo "Running Grype installer..."
echo "  ARCH: ${ARCH}"
echo "  INSTALL_PATH: ${INSTALL_PATH}"
echo "  VERIFY_CHECKSUMS: ${VERIFY_CHECKSUMS}"
echo "  VERSION: ${VERSION}"

# Lookup tables of sha512 checksums of the grype binary, keyed by version,
# with one table per architecture.
